--
-- Table structure for table `materials`
--

CREATE TABLE `materials` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `company_id` bigint(20) UNSIGNED NOT NULL,
  `category_id` bigint(20) UNSIGNED NOT NULL,
  `code` varchar(150) NOT NULL,
  `short_code` varchar(255) DEFAULT NULL,
  `name` varchar(150) NOT NULL,
  `specification` text NOT NULL,
  `unit_id` bigint(20) UNSIGNED NOT NULL,
  `purchase_unit_id` bigint(20) UNSIGNED NOT NULL,
  `unit_conversion_rate` decimal(12,4) NOT NULL DEFAULT 1.0000,
  `spq` int(11) NOT NULL DEFAULT 1,
  `qty_bag` int(11) NOT NULL DEFAULT 0,
  `net_weight` decimal(12,2) NOT NULL DEFAULT 0.00,
  `gross_weight` decimal(12,2) NOT NULL DEFAULT 0.00,
  `sprue` decimal(12,2) NOT NULL DEFAULT 0.00,
  `cycle_time` decimal(8,2) NOT NULL DEFAULT 0.00,
  `shift_capacity` int(11) NOT NULL DEFAULT 0,
  `properties` enum('purchase','self_made','sub_contract','configure','asset','feature','expense','virtual','service') NOT NULL DEFAULT 'purchase',
  `color` varchar(20) DEFAULT NULL,
  `cavity` int(11) NOT NULL DEFAULT 0,
  `workshop_id` bigint(20) UNSIGNED NOT NULL,
  `cust_part_no` varchar(150) DEFAULT NULL,
  `cust_part_name` varchar(150) DEFAULT NULL,
  `delivery_location` varchar(100) DEFAULT NULL,
  `avatar` varchar(255) DEFAULT NULL,
  `enable_min_stock` tinyint(1) NOT NULL DEFAULT 0,
  `min_stock` decimal(8,2) NOT NULL DEFAULT 0.00,
  `enable_safety_stock` tinyint(1) NOT NULL DEFAULT 0,
  `safety_stock` decimal(8,2) NOT NULL DEFAULT 0.00,
  `enable_max_stock` tinyint(1) NOT NULL DEFAULT 0,
  `max_stock` decimal(8,2) NOT NULL DEFAULT 0.00,
  `reorder_point` decimal(8,2) NOT NULL DEFAULT 0.00,
  `description` text DEFAULT NULL,
  `mold_no` varchar(50) DEFAULT NULL,
  `supplier_id` bigint(20) UNSIGNED DEFAULT NULL,
  `is_hazardous` tinyint(1) NOT NULL DEFAULT 0,
  `storage_location_id` varchar(255) DEFAULT NULL,
  `enable_expired` tinyint(1) NOT NULL DEFAULT 0,
  `expiry_days` int(11) NOT NULL DEFAULT 0,
  `lead_time_days` int(11) NOT NULL DEFAULT 0,
  `status` enum('draft','active','phase_out','obsolete') NOT NULL,
  `drawing_no` varchar(150) DEFAULT NULL,
  `process_routes` varchar(150) DEFAULT NULL,
  `drawing_level` varchar(10) DEFAULT NULL,
  `revision_no` varchar(10) DEFAULT NULL,
  `tonnage_id` bigint(20) UNSIGNED DEFAULT NULL,
  `hs_code` varchar(50) DEFAULT NULL,
  `regrind_method` enum('inline','offline','no_regrind') DEFAULT NULL,
  `carton_category` enum('A','B','C','D','E') DEFAULT NULL,
  `carton_length` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `carton_width` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `carton_height` decimal(12,4) NOT NULL DEFAULT 0.0000,
  `dimension_unit_id` bigint(20) UNSIGNED DEFAULT NULL,
  `stacking_limit` int(11) NOT NULL DEFAULT 0,
  `is_inspection_required` tinyint(1) NOT NULL DEFAULT 0,
  `last_purchase_price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`images`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) UNSIGNED NOT NULL,
  `updated_by` bigint(20) UNSIGNED NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

